import {activeTimetableInfo} from './teaching-data.mjs';
import {today,shiftDate,csv} from './model.mjs';
export function createDirectoryUI(ui){
 const {esc,button,options,empty}=ui,$=s=>document.querySelector(s),profiles=new Map(),schedules=new Map(),classes=new Map(),results=new Map();let filters={},routeKey=null,timer=null,request=0,activeResult=null;
 async function api(path,opts={}){const response=await fetch('/api/directory'+path,{credentials:'same-origin',cache:'no-store',...opts,headers:{'Content-Type':'application/json',...opts.headers}}),data=await response.json();if(!response.ok)throw Error(data.error||'Directory request failed.');return data;}
 const init=p=>({q:p.get('q')||'',type:['student','staff','parent'].includes(p.get('type'))?p.get('type'):'people',letter:p.get('letter')||'all',inactive:p.get('inactive')==='true'?'true':'false',year:p.get('year')||'',page:p.get('page')||'1',pageSize:'24'});
 const from=()=>new URLSearchParams(filters).toString();
 const personHref=(id,tab='bio',context='')=>'#/person?'+new URLSearchParams({id,tab,...(context?{from:context}:{})});
 function avatar(p,size=''){return p.avatar?`<img class="directory-avatar ${size}" src="${esc(p.avatar)}" alt="${esc(p.name)}">`:`<span class="directory-avatar ${p.kind} ${size}" aria-hidden="true">${p.name.split(' ').map(s=>s[0]).slice(0,2).join('')}</span>`;}
 function badge(p){return p.kind==='student'?p.yearLabel:p.kind==='staff'?'Staff':'Parent';}
 function card(p){const link=personHref(p.id,'bio',from());return `<article class="directory-person-card"><a class="directory-person-main" href="${link}">${avatar(p)}<span><strong>${esc(p.name)}${p.kind==='parent'?` <small>(${p.recordNumber})</small>`:''}</strong><small>${esc(p.kind==='student'?p.groupName:p.kind==='staff'?p.jobTitle:p.childCount+' linked student'+(p.childCount===1?'':'s'))}</small>${p.email?`<small>${esc(p.email)}</small>`:''}</span></a><div class="directory-card-side"><span class="directory-kind">${esc(badge(p))}</span>${p.status!=='Active'?'<span class="badge draft">Inactive</span>':''}${button('✉','directory-contact',`data-id="${p.id}" aria-label="Contact ${esc(p.name)}" title="View contact information"`,'directory-mail')}<details class="directory-card-menu"><summary aria-label="More options for ${esc(p.name)}">•••</summary><div><a href="${link}">Bio</a>${p.kind!=='parent'?`<a href="${personHref(p.id,'schedule',from())}">Schedule</a>`:''}<a href="${personHref(p.id,'contacts',from())}">Contacts</a>${p.kind==='student'&&p.canTrack?`<a href="#/student?id=${p.id}&tab=grades">Grades</a>`:''}</div></details></div></article>`;}
 function page(params){const key=params.toString();if(routeKey!==key){filters=init(params);routeKey=key;}return `<div class="directory-heading"><div><h1>School Directory</h1><p id="directory-population">Fictional people and linked school records</p></div>${button('Export page','directory-export','','small')}</div><div class="directory-searchbar"><label class="sr-only" for="directory-search">Search by name, ID, email or test phone</label><input id="directory-search" type="search" placeholder="Search by name, ID, email or phone number" value="${esc(filters.q)}"><span aria-hidden="true">⌕</span></div><div class="directory-controls"><label class="field"><span>Show</span><select id="directory-type">${options([['people','People'],['student','Students'],['staff','Staff'],['parent','Parents / guardians']],filters.type)}</select></label><label class="directory-inactive"><input id="directory-inactive" type="checkbox" ${filters.inactive==='true'?'checked':''}>Show inactive individuals</label><label class="field directory-year"><span>Year</span><select id="directory-year" ${['staff','parent'].includes(filters.type)?'disabled':''}>${options([['','All years'],['FS1','FS1'],['FS2','FS2'],...Array.from({length:13},(_,i)=>[String(i+1),'Year '+String(i+1).padStart(2,'0')])],filters.year)}</select></label>${button('Clear filters','directory-clear','','small')}</div><nav class="directory-alphabet" aria-label="Last-name initial">${['all',...'ABCDEFGHIJKLMNOPQRSTUVWXYZ','#'].map(letter=>`<button data-action="directory-letter" data-letter="${letter}" ${filters.letter.toUpperCase()===letter.toUpperCase()?'class="active" aria-current="true"':''}>${letter==='all'?'All':letter}</button>`).join('')}</nav><section class="directory-results-panel"><div class="directory-result-bar"><p id="directory-result-meta" role="status">Loading directory…</p><div id="directory-pages"></div></div><div id="directory-people" class="directory-people-grid">${loadResults()}</div></section>`;}
 function loadResults(){const id=++request,key=from();if(results.has(key)){activeResult=results.get(key);setTimeout(()=>paint(),0);return activeResult.error?'<div class="error">'+esc(activeResult.error)+'</div>':activeResult.people.map(card).join('')||empty('No people found','Clear a filter or try another name.');}api('/search?'+key).then(data=>{results.set(key,data);if(id===request&&ui.route().path==='/directory'){activeResult=data;paint();}}).catch(error=>{if(id===request){activeResult={error:error.message};paint();}});return '<div class="empty">Loading directory…</div>';}
 function paint(){if(!$('#directory-people')||!activeResult)return;if(activeResult.error){$('#directory-result-meta').textContent='Directory unavailable';$('#directory-people').innerHTML='<div class="error">'+esc(activeResult.error)+'</div>'+button('Retry','directory-retry');return;}const d=activeResult;$('#directory-people').innerHTML=d.people.map(card).join('')||empty('No people found','Try another name, ID or phone number, or clear a filter.');$('#directory-result-meta').textContent=d.total+' matching people'+(d.total?' · '+(d.start+1)+'–'+(d.start+d.people.length):'');$('#directory-population').textContent=d.counts.students+' students · '+d.counts.staff+' staff · '+d.counts.parents+' parents / guardians · '+d.counts.inactive+' inactive demo records';$('#directory-pages').innerHTML=button('←','directory-page',`data-page="${d.page-1}" aria-label="Previous directory page" ${d.page<=1?'disabled':''}`,'small')+'<span>'+d.page+' / '+d.pages+'</span>'+button('→','directory-page',`data-page="${d.page+1}" aria-label="Next directory page" ${d.page>=d.pages?'disabled':''}`,'small');}
 function update(){if(ui.route().path!=='/directory'||!$('#directory-search'))return;filters.page='1';filters.q=$('#directory-search').value;filters.type=$('#directory-type').value;filters.inactive=String($('#directory-inactive').checked);filters.year=$('#directory-year').value;ui.replaceHash('#/directory?'+from());routeKey=ui.route().params.toString();$('#directory-people').innerHTML=loadResults();document.querySelectorAll('.directory-alphabet button').forEach(el=>{const active=el.dataset.letter.toUpperCase()===filters.letter.toUpperCase();el.classList.toggle('active',active);if(active)el.setAttribute('aria-current','true');else el.removeAttribute('aria-current');});}
 function fetchProfile(params){const id=params.get('id'),context=params.get('from')||'',key=id+'|'+context;if(!profiles.has(key)){profiles.set(key,{loading:true});api('/person?'+new URLSearchParams({id:id||'',from:context})).then(data=>profiles.set(key,data)).catch(error=>profiles.set(key,{error:error.message})).finally(()=>{if(ui.route().path==='/person'&&ui.route().params.get('id')===id&&ui.canRender())ui.render();});}return profiles.get(key);}
 function header(p,params){const tab=params.get('tab')||'bio',context=params.get('from')||'',back='#/directory'+(context?'?'+context:'');return `<div class="directory-profile-topline"><a class="btn small" href="${back}">← Directory</a><div class="directory-profile-navigation">${p.previousId?`<a class="btn small" href="${personHref(p.previousId,tab,context)}" aria-label="Previous person">←</a>`:'<button class="btn small" disabled aria-label="Previous person">←</button>'}<span>${p.position?p.position+' / '+p.totalMatches:'Profile'}</span>${p.nextId?`<a class="btn small" href="${personHref(p.nextId,tab,context)}" aria-label="Next person">→</a>`:'<button class="btn small" disabled aria-label="Next person">→</button>'}</div></div><div class="directory-profile-header"><div class="directory-profile-identity"><div>${avatar(p,'large')}${p.canUploadAvatar?`<label class="directory-upload">Change photo<input id="directory-avatar-file" type="file" accept="image/png,image/jpeg" hidden></label>${p.avatar?button('Remove photo','directory-remove-avatar',`data-id="${p.id}"`,'small'):''}`:''}</div><div><h1>${esc(p.name)}</h1><p>${esc(p.email||p.schoolId)}</p><small>${esc(p.kind==='student'?p.groupName:p.kind==='staff'?p.jobTitle:'Parent / guardian')} · <span class="${p.status==='Active'?'directory-active':''}">${esc(p.status)}</span></small></div>${button('✉','directory-contact',`data-id="${p.id}" aria-label="Contact ${esc(p.name)}"`,'small')}</div><div class="directory-account"><strong>Account</strong><span>Status: ${esc(p.status)}</span><span>Username: ${esc(p.username||'No login assigned')}</span>${p.kind==='staff'?`<span>Last test login: ${p.lastLoginAt?new Date(p.lastLoginAt).toLocaleString('en-GB',{timeZone:'Asia/Tashkent'}):'Not recorded'}</span>`:`<span>School ID: ${esc(p.schoolId)}</span>`}</div></div><nav class="tabs directory-profile-tabs" aria-label="Directory profile sections">${[['bio','Bio'],...(p.kind!=='parent'?[['schedule','Schedule']]:[['children','Children']]),['contacts','Contacts']].map(([name,label])=>`<a ${tab===name?'class="active" aria-current="page"':''} href="${personHref(p.id,name,context)}">${label}</a>`).join('')}${p.kind==='student'&&p.canTrack?`<a href="#/student?id=${p.id}">Daily overview</a><a href="#/student?id=${p.id}&tab=grades">Grades</a><a href="#/cards?student=${p.id}">Reports</a>`:''}</nav>`;}
 const value=v=>v?esc(Array.isArray(v)?v.join(', '):v):'<span class="muted">Not recorded</span>';
 function info(title,rows){return `<section class="panel directory-info-panel"><div class="panel-head"><h2>${title}</h2></div><dl>${rows.map(([label,data])=>'<dt>'+esc(label)+'</dt><dd>'+value(data)+'</dd>').join('')}</dl></section>`;}
 function bio(p){const identity=info('Identity',[['Name',p.name],['Preferred name',p.preferredName],['Title',p.title],['School ID',p.schoolId],...(p.kind!=='student'?[['Directory ID',p.recordNumber]]:[])]),role=info(p.kind==='student'?'School placement':'School role',p.kind==='student'?[['Year',p.yearLabel],['Form',p.groupName],['Form tutor',p.formTutor?.name],['Enrollment date',p.enrolledOn],['Status',p.status],...(p.leftOn?[['Left school',p.leftOn]]:[])]:p.kind==='staff'?[['Role',p.jobTitle],['Phase',p.phase],['Curriculum area',p.area],['Usual classroom',p.usualRoom||'Shared specialist spaces'],['Joined school',p.employmentStart]]:[['Role','Parent / guardian'],['Linked students',p.children.map(c=>c.name)],['Household',p.households.map(h=>h.label)]]),personal=info('Personal information',[['Date of birth',p.dateOfBirth||(!p.canReadPrivate?'Restricted':'')],['Sex',p.sex],['Race',p.race],['Ethnicity',p.ethnicity],['Languages',p.languages]]),contact=info('Contact details',[['Phone',p.phone||(!p.canReadPrivate?'Restricted':'')],['Email',p.email],['Address',p.address||(!p.canReadPrivate?'Restricted':'')]]);return `<div class="directory-bio-grid"><div>${identity}${role}${contact}</div><div>${personal}${p.kind==='staff'?info('Teaching credentials',[['Subjects / areas',p.certifications],['Credential status',p.certifications.length?'Demo curriculum allocation on file':'Not recorded']]):related(p)}${p.kind==='student'?info('Record links',[['Tracking','The same student ID links attendance, assessments and school reports.'],['Access',p.canTrack?'Daily overview, Grades and Reports are available above.':'Tracking is available to allocated staff and the report reviewer.']]):''}</div></div>`;}
 function related(p){return `<section class="panel directory-info-panel"><div class="panel-head"><h2>${p.kind==='parent'?'Linked students':'Parents / guardians'}</h2></div><div class="directory-related">${(p.kind==='parent'?p.children:p.parents).map(r=>`<a href="${personHref(r.id)}">${avatar(r)}<span><strong>${esc(r.name)}</strong><small>${esc(r.groupName||r.relationship||'Parent / guardian')}</small></span><span>↗</span></a>`).join('')||'<p class="muted">No linked records.</p>'}</div></section>`;}
 function contacts(p){if(!p.canReadPrivate)return '<section class="panel"><div class="panel-body"><h2>Contacts</h2><p class="muted">Emergency, medical and household details are available to allocated staff and the test reviewer.</p></div></section>';return `<div class="directory-contact-grid"><section class="panel directory-info-panel"><div class="panel-head"><h2>${p.kind==='parent'?'Family contact':'Emergency contacts'}</h2></div><div class="directory-contact-cards">${p.kind==='parent'?`<div><strong>${esc(p.name)}</strong><p>${esc(p.phone)}</p><p>${esc(p.email)}</p><p>${esc(p.address)}</p>${related(p)}</div>`:p.emergencyContacts.length?p.emergencyContacts.map(c=>`<div><strong>${c.id?`<a href="${personHref(c.id)}">${esc(c.name)}</a>`:esc(c.name)}</strong><small>${esc(c.relationship||'Emergency contact')}${c.priority?' · Priority '+c.priority:''}</small><p>${esc(c.phone)}</p><p>${esc(c.email)}</p>${c.canCollect!==undefined?'<small>Collection permission: '+(c.canCollect?'Yes (demo)':'No')+'</small>':''}</div>`).join(''):'<p class="muted">None recorded.</p>'}</div></section><section class="panel directory-info-panel"><div class="panel-head"><h2>Medical</h2></div><div class="directory-contact-cards"><div><strong>${esc(p.medical?.summary||'No medical information recorded')}</strong>${p.medical?.notes?'<p>'+esc(p.medical.notes)+'</p>':''}${p.medical?.contact?`<hr><strong>${esc(p.medical.contact.name)}</strong><p>${esc(p.medical.contact.phone)}</p><p>${esc(p.medical.contact.email)}</p>`:''}<small>Fictional test information. No clinical instructions are provided.</small></div></div></section></div>`;}
 function schedule(p,params){const date=params.get('date')||(activeTimetableInfo()?.testDate||today()),key=p.id+'|'+date;if(!schedules.has(key)){schedules.set(key,{loading:true});api('/schedule?'+new URLSearchParams({id:p.id,date})).then(data=>schedules.set(key,data)).catch(error=>schedules.set(key,{error:error.message})).finally(()=>{if(ui.route().path==='/person'&&ui.route().params.get('id')===p.id&&ui.route().params.get('tab')==='schedule'&&ui.canRender())ui.render();});}const data=schedules.get(key);return `<div class="directory-schedule-heading"><h2>Schedule</h2><div class="actions">${button('←','directory-date','data-days="-1" aria-label="Previous schedule day"','small')}<label class="sr-only" for="directory-schedule-date">Schedule date</label><input type="date" id="directory-schedule-date" value="${esc(date)}">${button('→','directory-date','data-days="1" aria-label="Next schedule day"','small')}</div><small>Demonstration timetable</small></div>${data.loading?empty('Loading schedule',''):data.error?'<div class="error">'+esc(data.error)+'</div>':data.lessons.length?`<section class="panel"><div class="table-wrap"><table class="data-table directory-schedule-table"><thead><tr><th>Period</th><th>Time</th><th>Class</th><th>Location</th><th>Students</th></tr></thead><tbody>${data.lessons.map(l=>`<tr><td>${esc(l.period)}</td><td>${l.from}–${l.to}</td><td><a href="#/directory-class?id=${l.classId}">${esc(l.className)}</a><small><a href="${personHref(l.teacherId)}">${esc(l.teacher)}</a></small></td><td>${esc(l.room)}</td><td>${l.studentCount}</td></tr>`).join('')}</tbody></table></div></section><p class="directory-demo-note">${activeTimetableInfo()?'Active 2026–27 test timetable · class membership and registers are linked.':'Sample weekday schedule, not a conflict-free whole-school timetable.'}</p>`:empty('No scheduled lessons','Choose a weekday or an active teaching member of staff.')}`;}
 function profile(params){const p=fetchProfile(params);if(p.loading)return empty('Loading directory profile','');if(p.error)return '<div class="error">'+esc(p.error)+'</div><a class="btn" href="#/directory">Directory</a>';const tab=params.get('tab')||'bio';return header(p,params)+`<div id="page-error" class="error" role="alert"></div><div class="directory-profile-content">${tab==='contacts'?contacts(p):tab==='schedule'&&p.kind!=='parent'?schedule(p,params):tab==='children'&&p.kind==='parent'?related(p):bio(p)}</div>`;}
 function classPage(params){const id=params.get('id');if(!classes.has(id)){classes.set(id,{loading:true});api('/class?'+new URLSearchParams({id})).then(data=>classes.set(id,data)).catch(error=>classes.set(id,{error:error.message})).finally(()=>{if(ui.route().path==='/directory-class'&&ui.canRender())ui.render();});}const c=classes.get(id);if(c.loading)return empty('Loading class roster','');if(c.error)return '<div class="error">'+esc(c.error)+'</div>';return `<div class="directory-heading"><div><h1>${esc(c.name)}</h1><p><a href="${personHref(c.teacherId,'schedule')}">${esc(c.teacher)}</a> · ${esc(c.room)} · ${c.students.length} students</p></div><div class="actions"><a class="btn small" href="#/directory">Directory</a>${c.canOpen?`<a class="btn primary small" href="#/classes?class=${c.id}">Open class workspace</a>`:''}</div></div><section class="panel directory-roster-panel"><div class="table-wrap"><table class="data-table"><thead><tr><th>Student</th><th>School ID</th><th>Form</th><th>Profile</th></tr></thead><tbody>${c.students.map(s=>`<tr><td><a href="${personHref(s.id)}">${esc(s.name)}</a></td><td>${esc(s.schoolId)}</td><td>${esc(s.groupName)}</td><td><a class="btn small" href="${personHref(s.id)}">Open</a>${s.canTrack?` <a class="btn small" href="#/student?id=${s.id}&tab=grades">Grades</a>`:''}</td></tr>`).join('')}</tbody></table></div></section>`;}
 async function showContact(id){try{const p=await api('/person?'+new URLSearchParams({id}));ui.openDialog('Contact information',`<h3>${esc(p.name)}</h3><dl class="directory-contact-popup"><dt>Email</dt><dd>${value(p.email)}</dd><dt>Phone</dt><dd>${value(p.phone||(!p.canReadPrivate?'Restricted':''))}</dd></dl><p class="muted">These are fictional test contacts. No email or phone call is sent.</p>`,button('Close','close')+`<a class="btn primary" href="${personHref(id,'contacts')}" data-action="directory-close-profile">Open contacts</a>`);}catch(error){ui.error(error.message);}}
 async function uploadAvatar(input){const file=input.files?.[0];if(!file)return;try{if(!['image/png','image/jpeg'].includes(file.type)||file.size>1024*1024)throw Error('Choose a PNG or JPEG image up to 1 MB.');const data=await new Promise((resolve,reject)=>{const reader=new FileReader();reader.onload=()=>resolve(reader.result);reader.onerror=()=>reject(Error('Could not read this image.'));reader.readAsDataURL(file);});const image=new Image();image.src=data;await image.decode();if(image.width>4096||image.height>4096)throw Error('Use an image no larger than 4096 × 4096 pixels.');const p=fetchProfile(ui.route().params);await api('/avatar',{method:'PUT',body:JSON.stringify({id:p.id,data,expectedRevision:p.profileRevision})});profiles.clear();results.clear();ui.render();ui.toast('Demo profile photo saved.');}catch(error){ui.error(error.message);input.value='';}}
 function action(action,a){if(action==='directory-letter'){filters.letter=a.dataset.letter;filters.page='1';update();return true;}if(action==='directory-page'){filters.page=a.dataset.page;ui.replaceHash('#/directory?'+from());routeKey=ui.route().params.toString();$('#directory-people').innerHTML=loadResults();return true;}if(action==='directory-clear'){filters=init(new URLSearchParams());$('#directory-search').value='';$('#directory-type').value='people';$('#directory-inactive').checked=false;$('#directory-year').value='';$('#directory-year').disabled=false;update();return true;}if(action==='directory-retry'){results.delete(from());$('#directory-people').innerHTML=loadResults();return true;}if(action==='directory-contact'){void showContact(a.dataset.id);return true;}if(action==='directory-close-profile'){ui.closeDialog(true);return true;}if(action==='directory-date'){const date=shiftDate($('#directory-schedule-date').value,Number(a.dataset.days));changeDate(date);return true;}if(action==='directory-remove-avatar'){const p=fetchProfile(ui.route().params);api('/avatar',{method:'PUT',body:JSON.stringify({id:p.id,data:null,expectedRevision:p.profileRevision})}).then(()=>{profiles.clear();results.clear();ui.render();}).catch(error=>ui.error(error.message));return true;}if(action==='directory-export'){if(activeResult?.people)ui.download('directory-page.csv',csv([['School ID','Name','Type','Status','Year / role','Test email','Test phone'],...activeResult.people.map(p=>[p.schoolId,p.name,p.kind,p.status,p.groupName||p.jobTitle,p.email,p.phone])]));return true;}return false;}
 function changeDate(date){ui.navigate('/person',{...Object.fromEntries(ui.route().params),tab:'schedule',date});}
 function input(t){if(t.id==='directory-search'){filters.letter='all';clearTimeout(timer);timer=setTimeout(update,180);}}
 function change(t){if(['directory-type','directory-inactive','directory-year'].includes(t.id)){if(t.id==='directory-type'){const disabled=['staff','parent'].includes(t.value);$('#directory-year').disabled=disabled;if(disabled)$('#directory-year').value='';}update();}if(t.id==='directory-schedule-date')changeDate(t.value);if(t.id==='directory-avatar-file')void uploadAvatar(t);}
 return{page,profile,classPage,action,input,change};
}
